// The private packs of the DM encyclopedia (compendio delle regole, fase 2): the texts of the manuals that are not in
// the SRD (Manuale del Giocatore, Guida del DM, Xanathar, Tasha), generated by the GM from their own PDFs and imported
// in this browser only. Never in the bundle, the repository, the scene or the room. Pure functions: the format, its
// validation and the merge of a pack's rules with the SRD compendium (src/rules-reference-it.json).
//
// A pack: { format, schemaVersion, id, title, badge, generatedAt?, rules?: { topics, entries }, spells?: { [spellId]:
// { description, higherLevels } }, classFeatures?: { [featureId]: text }, classFeatureTables?: { [featureId]: { [row]:
// text } } }. rules follows the schema of the SRD compendium; its topics reuse the SRD ids so the entries land under
// the same subjects.

export const PRIVATE_PACK_FORMAT = "take-initiative/private-pack";
export const PRIVATE_PACK_SCHEMA_VERSION = 1;
// The source of the entries that come from the SRD compendium, next to the packs' ids.
export const SRD_SOURCE = Object.freeze({ id: "srd", title: "D&D 5e SRD 5.1 italiano", badge: "SRD" });
// The manuals a pack can carry, by the id the catalogs already use as a spell's or a feature's source.
export const PRIVATE_PACK_BOOKS = Object.freeze({
  phb2014: Object.freeze({ id: "phb2014", title: "Manuale del Giocatore", badge: "PHB" }),
  dmg2014: Object.freeze({ id: "dmg2014", title: "Guida del Dungeon Master", badge: "DMG" }),
  xanathar: Object.freeze({ id: "xanathar", title: "Guida Omnicomprensiva di Xanathar", badge: "XGE" }),
  tasha: Object.freeze({ id: "tasha", title: "Calderone Omnicomprensivo di Tasha", badge: "TCE" }),
  "ranger-revised": Object.freeze({ id: "ranger-revised", title: "Unearthed Arcana: Ranger rivisto", badge: "UA" }),
});

// The texts of the spells in the packs: Map spellId → { description, higherLevels, pack }. A later pack wins.
export function privateSpellTexts(packs = []) {
  const texts = new Map();
  for (const pack of packs) {
    for (const [id, spell] of Object.entries(pack?.spells || {})) {
      texts.set(id, { description: spell.description, higherLevels: spell.higherLevels || "", pack: pack.id });
    }
  }
  return texts;
}

// "Il testo è nel pacchetto privato «Guida Omnicomprensiva di Xanathar»: importalo dall'Enciclopedia DM (Pacchetti)."
export function privateTextMissingNote(bookId) {
  const book = PRIVATE_PACK_BOOKS[bookId];
  const name = book ? `«${book.title}»` : "del manuale";
  return `Il testo è nel pacchetto privato ${name}: importalo dall'Enciclopedia DM (Pacchetti).`;
}

const ID = /^[a-z0-9][a-z0-9-]*$/u;
const MAX_BADGE = 6;

const isObject = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
const isText = (value) => typeof value === "string" && value.trim() !== "";
const strings = (value) => Array.isArray(value) && value.every((item) => typeof item === "string");

// Why a pack's rules are unusable, or "".
function rulesProblem(rules) {
  if (!isObject(rules) || !Array.isArray(rules.topics) || !Array.isArray(rules.entries)) return "le regole non hanno argomenti e voci";
  for (const topic of rules.topics) {
    if (!isObject(topic) || !ID.test(String(topic.id)) || !isText(topic.name) || !Array.isArray(topic.sections)) return "un argomento non è valido";
    if (topic.sections.some((section) => !isObject(section) || !ID.test(String(section.id)) || !isText(section.name))) {
      return `una sezione di "${topic.name}" non è valida`;
    }
  }
  const ids = new Set();
  for (const entry of rules.entries) {
    if (!isObject(entry) || !ID.test(String(entry.id)) || !isText(entry.name) || !isText(entry.text)) return "una voce non è valida";
    if (ids.has(entry.id)) return `la voce "${entry.id}" è ripetuta`;
    ids.add(entry.id);
    if (!ID.test(String(entry.topic)) || (entry.section != null && !ID.test(String(entry.section)))) return `la voce "${entry.id}" non ha un argomento valido`;
    if (!Number.isInteger(entry.page) || entry.page < 1) return `la voce "${entry.id}" non ha la pagina`;
    if (!strings(entry.aliases) || !strings(entry.related)) return `alias o rimandi di "${entry.id}" non sono validi`;
  }
  return "";
}

// { pack } or { error } (in Italian, for the panel) from a parsed file.
export function validatePrivatePack(value) {
  if (!isObject(value) || value.format !== PRIVATE_PACK_FORMAT) return { error: "Non è un pacchetto di Take Initiative." };
  if (value.schemaVersion !== PRIVATE_PACK_SCHEMA_VERSION) return { error: `Versione del pacchetto non supportata: ${value.schemaVersion}.` };
  if (!ID.test(String(value.id)) || value.id === SRD_SOURCE.id) return { error: "Il pacchetto non ha un identificativo valido." };
  if (!isText(value.title) || !isText(value.badge) || value.badge.trim().length > MAX_BADGE) return { error: "Il pacchetto non ha titolo o sigla." };
  const problem = value.rules === undefined ? "" : rulesProblem(value.rules);
  if (problem) return { error: `Pacchetto "${value.title}": ${problem}.` };
  if (value.spells !== undefined && !(isObject(value.spells) && Object.values(value.spells).every((spell) => (
    isObject(spell) && typeof spell.description === "string" && (spell.higherLevels === undefined || typeof spell.higherLevels === "string")
  )))) return { error: `Pacchetto "${value.title}": i testi degli incantesimi non sono validi.` };
  if (value.classFeatures !== undefined && !(isObject(value.classFeatures) && Object.values(value.classFeatures).every((text) => typeof text === "string"))) {
    return { error: `Pacchetto "${value.title}": i testi delle capacità non sono validi.` };
  }
  if (value.classFeatureTables !== undefined && !(isObject(value.classFeatureTables) && Object.values(value.classFeatureTables).every((table) => (
    isObject(table) && Object.values(table).every((text) => typeof text === "string")
  )))) return { error: `Pacchetto "${value.title}": le tabelle delle capacità non sono valide.` };
  return { pack: value };
}

// { pack } or { error } from the text of a file.
export function parsePrivatePack(text) {
  let value;
  try {
    value = JSON.parse(String(text ?? ""));
  } catch {
    return { error: "Il file non è un JSON leggibile." };
  }
  return validatePrivatePack(value);
}

// What the panel shows of a pack, without its texts.
export function privatePackSummary(pack, bytes = 0) {
  return {
    id: pack.id,
    title: pack.title.trim(),
    badge: pack.badge.trim(),
    generatedAt: typeof pack.generatedAt === "string" ? pack.generatedAt : "",
    rules: pack.rules?.entries?.length || 0,
    spells: Object.keys(pack.spells || {}).length,
    classFeatures: Object.keys(pack.classFeatures || {}).length,
    bytes: Number(bytes) || 0,
  };
}

// "12 regole · 30 incantesimi · 4 capacità", the counts that are not zero.
export function privatePackContentsLabel(summary) {
  const parts = [
    [summary.rules, "regola", "regole"],
    [summary.spells, "incantesimo", "incantesimi"],
    [summary.classFeatures, "capacità", "capacità"],
  ].filter(([count]) => count > 0).map(([count, one, many]) => `${count} ${count === 1 ? one : many}`);
  return parts.join(" · ") || "nessun testo";
}

// The SRD compendium with the rules of the packs, in the schema of rules-reference-it.json plus, on every entry,
// source: "srd" or the pack's id, and sources: [SRD_SOURCE, ...packs' { id, title, badge }]. A pack's topics join the
// SRD ones by id (new sections after the SRD's), new topics come after. A pack entry whose id is already taken is
// left out and counted in skipped, so a pack never hides an SRD entry. The order of the packs is the order given.
export function mergeRulesCatalogs(srd, packs = []) {
  const topics = (srd?.topics || []).map((topic) => ({ ...topic, sections: [...(topic.sections || [])] }));
  const entries = (srd?.entries || []).map((entry) => ({ ...entry, source: SRD_SOURCE.id }));
  const sources = [SRD_SOURCE];
  const taken = new Set(entries.map((entry) => entry.id));
  let skipped = 0;
  for (const pack of packs) {
    if (!pack?.rules) continue;
    sources.push({ id: pack.id, title: pack.title.trim(), badge: pack.badge.trim() });
    for (const packTopic of pack.rules.topics) {
      let topic = topics.find((item) => item.id === packTopic.id);
      if (!topic) {
        topic = { id: packTopic.id, name: packTopic.name, sections: [] };
        topics.push(topic);
      }
      for (const section of packTopic.sections) {
        if (!topic.sections.some((item) => item.id === section.id)) topic.sections.push({ id: section.id, name: section.name });
      }
    }
    for (const entry of pack.rules.entries) {
      if (taken.has(entry.id) || !topics.some((topic) => topic.id === entry.topic)) {
        skipped += 1;
        continue;
      }
      taken.add(entry.id);
      entries.push({ ...entry, section: entry.section ?? null, optional: Boolean(entry.optional), source: pack.id });
    }
  }
  return { ...srd, topics, entries, sources, skipped };
}

// The sources of a merged catalog with how many entries each has: [{ id, title, badge, count }], in the catalog's
// order, the sources without entries left out.
export function rulesSourceCounts(catalog) {
  const counts = new Map();
  for (const entry of catalog?.entries || []) counts.set(entry.source, (counts.get(entry.source) || 0) + 1);
  return (catalog?.sources || []).filter((source) => counts.has(source.id)).map((source) => ({ ...source, count: counts.get(source.id) }));
}

// The merged catalog without the entries of the hidden sources (a Set of ids): the Rules tab's filter. Topics and
// sources stay; rulesTree leaves out the sections left empty.
export function filterRulesCatalogBySource(catalog, hidden = new Set()) {
  if (!hidden.size) return catalog;
  return { ...catalog, entries: (catalog?.entries || []).filter((entry) => !hidden.has(entry.source)) };
}
